import base64
import io
import os
from typing import Any, Dict, Optional

import boto3


def _normalize_text_from_blocks(blocks: list[dict]) -> str:
    lines = []
    current_line = []

    for block in blocks:
        btype = block.get("BlockType")
        text = block.get("Text", "")
        if not text:
            continue

        if btype == "LINE":
            lines.append(text)
        elif btype == "WORD":
            current_line.append(text)

    if lines:
        return "\n".join(lines).strip()

    return " ".join(current_line).strip()


def _extract_layout(result: Dict[str, Any]) -> Dict[str, Any]:
    blocks = result.get("Blocks", []) or []
    text = _normalize_text_from_blocks(blocks)

    pages = []
    for block in blocks:
        if block.get("BlockType") == "PAGE":
            pages.append(
                {
                    "page": block.get("Page"),
                    "confidence": block.get("Confidence"),
                    "geometry": block.get("Geometry"),
                }
            )

    return {
        "text": text,
        "pages": pages,
        "blocks": blocks,
        "raw": result,
    }


def extract_text_and_layout(image_path: str, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Extract plain text and layout information from a scanned document image using Amazon Textract.

    Requires AWS credentials via the standard boto3 credential chain, e.g.:
    - AWS_ACCESS_KEY_ID
    - AWS_SECRET_ACCESS_KEY
    - AWS_SESSION_TOKEN (optional)
    - AWS_REGION / region_name (optional)
    """
    if region_name is None:
        region_name = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION") or "us-east-1"

    client = boto3.client("textract", region_name=region_name)

    with open(image_path, "rb") as f:
        document_bytes = f.read()

    response = client.detect_document_text(Document={"Bytes": document_bytes})
    return _extract_layout(response)


def extract_text_and_layout_from_bytes(image_bytes: bytes, region_name: Optional[str] = None) -> Dict[str, Any]:
    if region_name is None:
        region_name = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION") or "us-east-1"

    client = boto3.client("textract", region_name=region_name)
    response = client.detect_document_text(Document={"Bytes": image_bytes})
    return _extract_layout(response)


def extract_text_and_layout_from_base64(image_b64: str, region_name: Optional[str] = None) -> Dict[str, Any]:
    image_bytes = base64.b64decode(image_b64)
    return extract_text_and_layout_from_bytes(image_bytes, region_name=region_name)
